package com.collectiq.web;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.ResponseEntity;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.util.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
@RestController @RequestMapping("/api/whatsapp/webhook") public class WhatsAppWebhookController{
 private final JdbcTemplate db;@Value("${WHATSAPP_VERIFY_TOKEN:}")String verifyToken;@Value("${WHATSAPP_APP_SECRET:}")String appSecret;
 public WhatsAppWebhookController(JdbcTemplate d){db=d;}
 @GetMapping public ResponseEntity<String> verify(@RequestParam("hub.mode")String mode,@RequestParam("hub.verify_token")String token,@RequestParam("hub.challenge")String challenge){return "subscribe".equals(mode)&&!verifyToken.isBlank()&&MessageDigest.isEqual(verifyToken.getBytes(StandardCharsets.UTF_8),token.getBytes(StandardCharsets.UTF_8))?ResponseEntity.ok(challenge):ResponseEntity.status(403).body("Forbidden");}
 @PostMapping public ResponseEntity<Void> receive(@RequestHeader(value="X-Hub-Signature-256",required=false)String sig,@RequestBody byte[] raw){if(appSecret.isBlank()||sig==null||!valid(sig,raw))return ResponseEntity.status(401).build();try{var root=new com.fasterxml.jackson.databind.ObjectMapper().readTree(raw);var entries=root.path("entry");for(var entry:entries)for(var change:entry.path("changes")){var value=change.path("value");for(var status:value.path("statuses")){String waId=status.path("id").asText();String state=status.path("status").asText();String recipient=status.path("recipient_id").asText();db.update("insert into whatsapp_message_events(provider_message_id,status,recipient,raw_payload,received_at) values(?,?,?,?::jsonb,now()) on conflict(provider_message_id,status) do nothing",waId,state,recipient,new String(raw,StandardCharsets.UTF_8));db.update("update reminder_approvals set status=case when ?='failed' then 'FAILED' when ?='delivered' then 'DELIVERED' when ?='read' then 'READ' else status end where external_message_id=? and status in ('SENT','DELIVERED','READ')",state,state,waId);}}}catch(Exception e){return ResponseEntity.badRequest().build();}return ResponseEntity.ok().build();}
 private boolean valid(String sig,byte[] raw){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(appSecret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String expected="sha256="+HexFormat.of().formatHex(m.doFinal(raw));return MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),sig.getBytes(StandardCharsets.UTF_8));}catch(Exception e){return false;}}
}